import { h, render, Component } from 'preact';

import constants from './../constants';

const INSTRUCTIONS = '${name}: Nombre de la Alarma\n${variable}: Nombre de la Variable\n${value}: Valor de la Variable\n${timestamp}: Estampa de tiempo de la variable';

class UpdateForm extends Component {

  constructor(props) {
    super(props);

    this.state = {
      units_: [],
      is_timeout: false
    };
  }

  componentDidMount() {
    let o = this.props.item;
    if (!o) {
      let msg = 'No se encontró la información de la alarma';
      alert(msg);
      return;
    }

    let inputName = document.querySelector('#input-u-name');
    let inputColor = document.querySelector('#input-u-color');
    let inputMessage = document.querySelector('#input-u-message');
    let inputStatus = document.querySelector('#input-u-status');      

    inputName.value = o.name;
    inputColor.value = o.color;
    inputMessage.value = o.message;
    inputStatus.checked = o.status;

    if (o.is_timeout) {
      let inputIsTimeout = document.querySelector('#input-u-is-timeout');
      inputIsTimeout.checked = o.is_timeout;

      this.setState({ is_timeout: o.is_timeout });

    } else {
      let inputExpression = document.querySelector('#input-u-expression');
      inputExpression.value = o.expression;
    }

    this.getUnits();
       
  }

  getUnits() {
    let self = this;

    let url = `${constants.URL_SERVER_UNITS}/list`;

    let xhr = $.ajax({
      url: url,
      type: constants.METHOD_GET,
      dataType: constants.JSON,
    });

    xhr.done((res, status, response) => {
      if (response.status == constants.STATUS_OK) {
        self.setState({ units_: res.docs }, () => {

          let o = this.props.item;
          if (o) {
            let inputUnit = document.querySelector('#input-u-unit');
            if (o.unit_id) inputUnit.value = o.unit_id;
          }

        });

      } else if (response.status == constants.STATUS_ACCEPTED) {
        alert(res.message);
      }
    });

    xhr.fail((res, status, respose) => {
      if (res.responseJSON) {
        let json = res.responseJSON;
        alert(json.message);
      } else {
        alert(constants.MESSAGE_ERROR);
      }
    });
  }

  handleUpdate() {
    let self = this;

    let fn = (evt) => {
      evt.preventDefault();

      let o = this.props.item;
      if (!o) {
        let msg = 'No se encontró la información de la alarma';
        alert(msg);
        return;
      }      

      let inputName = document.querySelector('#input-u-name');
      let inputUnit = document.querySelector('#input-u-unit');
      let inputColor = document.querySelector('#input-u-color');
      let inputIsTimeout = document.querySelector('#input-u-is-timeout');
      let inputTimeout = document.querySelector('#input-u-timeout');
      let inputExpression = document.querySelector('#input-u-expression');
      let inputMessage = document.querySelector('#input-u-message');
      let inputSound = document.querySelector('#input-u-sound');
      let inputStatus = document.querySelector('#input-u-status');

      let name = inputName.value.trim();
      let unit = inputUnit.value.trim();
      let color = inputColor.value.trim();
      let is_timeout = inputIsTimeout.checked;
      let message = inputMessage.value.trim();
      let sound = inputSound.value.trim();
      let status = inputStatus.checked;


      let expression, timeout;

      if (is_timeout) {
        timeout = inputTimeout.value.trim();
        timeout = parseInt(timeout);
      } else {
        expression = inputExpression.value.trim();
      }

      let json = {};

      if (unit !== '') {
        let unit_id = parseInt(unit);
        json.unit_id = unit_id;
      }

      if (sound == '') {
        sound = -1;
      } else {
        sound = parseInt(sound);
      }

      json.name = name;
      json.color = color;
      json.expression = expression;
      json.is_timeout = is_timeout;
      json.timeout = timeout;
      json.message = message;
      json.sound = sound;
      json.status = status;

      self.props.onUpdate(json, o.id);
    };

    return fn;
  }

  handleChangeTimeout() {
    let self = this;

    let fn = (evt) => {
      let value = evt.target.checked;
      self.setState({ is_timeout: value });
    };

    return fn;
  }

  handleBack() {
    let self = this;

    let fn = () => {
      self.props.onBack();
    };

    return fn;
  }

  createOptUnit() {
    let self = this;

    let fn = (item, index) => {
      return <option key={item.id} value={item.value}>{item.name}</option>;
    };

    return fn;
  }  

  render(props, state) {
    return (
      <section>
        <div className="row">
          <div className="col-md-12">
            <h3>Editar Alarma</h3>

            <form onSubmit={this.handleUpdate()} >

              <div className="form-group">
                <label htmlFor="input-u-name">Nombre</label>
                <input type="text" className="form-control" id="input-u-name" placeholder="Nombre" />
              </div>

              <div className="form-group">
                <label htmlFor="input-u-unit">Unidad</label>
                <select id="input-u-unit" className="form-control">
                  <option selected value="-1">Unidad</option>
                  {state.units_.map(this.createOptUnit())}
                </select>
              </div>

              <div className="form-group">
                <label htmlFor="input-u-color">Color</label>
                <input type="text" className="form-control" id="input-u-color" placeholder="Color" />
              </div>

              <div className="form-check">
                <input type="checkbox" class="form-check-input" id="input-u-is-timeout" onChange={this.handleChangeTimeout()} />
                <label class="form-check-label" htmlFor="input-u-is-timeout">Tiempo de Espera</label>
              </div>

              <br />

              <div className="form-group" hidden={!state.is_timeout}>
                <label htmlFor="input-u-timeout">Tiempo</label>
                <input type="text" className="form-control" id="input-u-timeout" placeholder="Tiempo (Minutos)" />
              </div>

              <div className="form-group" hidden={state.is_timeout}>
                <label htmlFor="input-u-expression">
                  Expresión Booleana
                  <br />
                  {'${value}: Valor de la Variable'}
                </label>
                <textarea className="form-control" id="input-u-expression" placeholder="Expresión Booleana" />
              </div>

              <div className="form-group">
                <label htmlFor="input-u-message">
                  Mensaje
                  <br />
                  {'${name}: Nombre de la Alarma'}
                  <br />
                  {'${variable}: Nombre de la Variable'}
                  <br />
                  {'${value}: Valor de la Variable'}
                  <br />
                  {'${timestamp}: Estampa de tiempo de la variable'}
                </label>
                <input type="text" className="form-control" id="input-u-message" placeholder="Mensaje" />
              </div>

              <div className="form-group">
                <label htmlFor="input-u-sound">Sonido</label>
                <select id="input-u-sound" className="form-control">
                  <option selected value="-1">Sin sonido</option>
                  <option value="1">Advertencia</option>
                  <option value="2">Peligro</option>
                </select>
              </div>              

              <div className="form-check">
                <input type="checkbox" class="form-check-input" id="input-u-status" />
                <label class="form-check-label" htmlFor="input-u-status">Activada</label>
              </div>

              <div className="form-group col-md-12">
                <br />
                <br />
                <button type="button" className="btn btn-warning" onClick={this.handleBack()}>Cancelar</button>
                <button type="submit" className="btn btn-success">Guardar</button>
              </div>

            </form>
          </div>
        </div>
      </section>
    );
  }
}

export default UpdateForm;
