import { h, render, Component } from 'preact';

import constants from './../constants.js';

import Table from './table.jsx';
import CreateForm from './create-form.jsx';
import UpdateForm from './update-form.jsx';
import OptionsPanel from './options-panel.jsx';

const ENTER = 13;
const TABLE = 0;
const CREATE_FORM = 1;
const UPDATE_FORM = 2;
const OPTIONS_PANEL = 3;

class Content extends Component {

  constructor() {
    super();

    this.state = {
      items: [],
      item: false,
      search: '',
      form: TABLE
    };
  }

  componentDidMount() {
    this.getAlarms();
  }

  getAlarms() {
    let self = this;

    let url = `${constants.URL_SERVER_ALARMS}/list`;

    let xhr = $.ajax({
      url: url,
      type: constants.METHOD_GET,
      dataType: constants.JSON,
    });

    xhr.done((res, status, response) => {
      if (response.status == constants.STATUS_OK) {
        self.setState({ items: res.docs });

      } else if (response.status == constants.STATUS_ACCEPTED) {
        alert(res.message);
      }
    });

    xhr.fail((res, status, respose) => {
      if (res.responseJSON) {
        let json = res.responseJSON;
        alert(json.message);
      } else {
        alert(constants.MESSAGE_ERROR);
      }
    });
  }

  getAlarmsForSearch(value) {
    let self = this;

    let url = `${constants.URL_SERVER_ALARMS}/list?search=${value}`;

    let xhr = $.ajax({
      url: url,
      type: constants.METHOD_GET,
      dataType: constants.JSON,
    });

    xhr.done((res, status, response) => {
      if (response.status == constants.STATUS_OK) {
        self.setState({ items: res.docs });

      } else if (response.status == constants.STATUS_ACCEPTED) {
        alert(res.message);
      }
    });

    xhr.fail((res, status, respose) => {
      if (res.responseJSON) {
        let json = res.responseJSON;
        alert(json.message);
      } else {
        alert(constants.MESSAGE_ERROR);
      }
    });
  }

  getAlarm() {
    let self = this;

    let fn = (json) => {
      let xhr = $.ajax({
        url: `${constants.URL_SERVER_ALARMS}/${json.id}`,
        type: constants.METHOD_GET,
        dataType: constants.JSON
      });

      xhr.done((res, status, response) => {
        if (response.status == constants.STATUS_OK) {
          self.getItem(null, res.doc);
        } else if (response.status == constants.STATUS_ACCEPTED) {
          self.getItem(res.message);
        }
      });

      xhr.fail((res, status, respose) => {
        if (res.responseJSON) {
          let json = res.responseJSON;
          alert(json.message);
        } else {
          alert(constants.MESSAGE_ERROR);
        }
      });
    };

    return fn;
  }

  addAlarm() {
    let self = this;

    let fn = (json) => {
      let xhr = $.ajax({
        url: constants.URL_SERVER_ALARMS,
        type: constants.METHOD_POST,
        contentType: constants.APPLICATION_JSON,
        data: JSON.stringify(json)
      });

      xhr.done((res, status, response) => {
        if (response.status == constants.STATUS_CREATED) {
          self.addItem(null, res.doc);
        } else if (response.status == constants.STATUS_ACCEPTED) {
          self.addItem(res.message);
        }
      });

      xhr.fail((res, status, respose) => {
        if (res.responseJSON) {
          let json = res.responseJSON;
          alert(json.message);
        } else {
          alert(constants.MESSAGE_ERROR);
        }
      });
    }

    return fn;
  }

  updateAlarm() {
    let self = this;

    let fn = (json, id) => {

      let xhr = $.ajax({
        url: `${constants.URL_SERVER_ALARMS}/${id}`,
        type: constants.METHOD_PUT,
        contentType: constants.APPLICATION_JSON,
        data: JSON.stringify(json)
      });

      xhr.done((res, status, response) => {
        if (response.status == constants.STATUS_OK) {
          self.updateItem(null, res.doc);
        } else if (response.status == constants.STATUS_ACCEPTED) {
          self.updateItem(res.message);
        }
      });

      xhr.fail((res, status, respose) => {
        if (res.responseJSON) {
          let json = res.responseJSON;
          alert(json.message);
        } else {
          alert(constants.MESSAGE_ERROR);
        }
      });
    }

    return fn;
  }

  deleteAlarm() {
    let self = this;

    let fn = (json) => {
      let xhr = $.ajax({
        url: `${constants.URL_SERVER_ALARMS}/${json.id}`,
        type: constants.METHOD_DELETE
      });

      xhr.done((res, status, response) => {
        if (response.status == constants.STATUS_OK) {
          self.removeItem(null, json);
        } else if (response.status == constants.STATUS_ACCEPTED) {
          self.removeItem(res.message);
        }
      });

      xhr.fail((res, status, respose) => {
        if (res.responseJSON) {
          let json = res.responseJSON;
          alert(json.message);
        } else {
          alert(constants.MESSAGE_ERROR);
        }
      });
    }

    return fn;
  }

  updateOptionsAlarm() {
    let self = this;

    let fn = (json, id) => {

      let xhr = $.ajax({
        url: `${constants.URL_SERVER_ALARMS}/${id}?update_relations=true`,
        type: constants.METHOD_PUT,
        contentType: constants.APPLICATION_JSON,
        data: JSON.stringify(json)
      });

      xhr.done((res, status, response) => {
        if (response.status == constants.STATUS_OK) {
          self.updateItem(null, res.doc);
        } else if (response.status == constants.STATUS_ACCEPTED) {
          self.updateItem(res.message);
        }
      });

      xhr.fail((res, status, respose) => {
        if (res.responseJSON) {
          let json = res.responseJSON;
          alert(json.message);
        } else {
          alert(constants.MESSAGE_ERROR);
        }
      });
    }

    return fn;
  }

  getItem(err, item) {
    let self = this;

    if (err) {
      alert(err);
      return;
    }

    self.setState({ item: item, form: UPDATE_FORM });
  }

  addItem(err, item) {
    if (err) {
      alert(err);
      return;
    }

    let items = this.state.items;
    items.push(item);
    this.setState({ form: TABLE, items: items });
  }

  updateItem(err, item) {
    if (err) {
      alert(err);
      return;
    }

    let items = this.state.items;
    for (let i = 0; i < items.length; i++) {
      let id = items[i].id;
      if (item.id == id) {
        items[i] = item;
        break;
      }
    }

    this.setState({ form: TABLE, items: items });
  }

  removeItem(err, item) {
    let self = this;

    if (!err) {
      let items = self.state.items;
      for (let i = 0; i < items.length; i++) {
        let id = items[i].id;
        if (item.id == id) {
          items.splice(i, 1);
          break;
        }
      }

      self.setState({ items: items });
    } else {
      alert(err);
    }
  }

  handleCreate() {
    let self = this;

    let fn = () => {
      self.setState({ form: CREATE_FORM });
    };

    return fn;
  }

  handleOptions() {
    let self = this;

    let fn = (json) => {

      self.setState({ form: OPTIONS_PANEL, item: json });
    };

    return fn;
  }

  handleChange() {
    let self = this;

    let fn = (evt) => {
      let value = evt.target.value;
      let space = ' ';
      let re = new RegExp(space, 'g');
      let nil = '';

      value = value.replace(re, nil);
      if (value == '') {
        self.getAlarms();
      }
    };

    return fn;
  }

  handleSearch() {
    let self = this;

    let fn = (evt) => {
      if (evt.which == ENTER) {
        evt.preventDefault();
        let search = evt.target.value;
        if (search) {
          if (search !== '') {
            search = search.toLowerCase();
            self.getAlarmsForSearch(search);
          }
        }
      }
    };

    return fn;
  }

  handleBack() {
    let self = this;

    let fn = () => {
      self.setState({ form: TABLE });
    }

    return fn;
  }

  render(props, state) {
    let self = this;

    let view = false;
    let form = state.form;

    let createForm = <CreateForm onCreate={self.addAlarm()} onBack={self.handleBack()} />
    let updateForm = <UpdateForm item={state.item} onUpdate={self.updateAlarm()} onBack={self.handleBack()} />
    let optionsPanel = <OptionsPanel item={state.item} onUpdateOptions={self.updateOptionsAlarm()} onBack={self.handleBack()} />

    let table = (() => {
      return (
        <div>
          <div className="row">
            <div className="col-md-3">
              <h4>Alarmas</h4>
            </div>

            <div className="col-md-6">
              <div className="form-group col-md-12">
                <input placeholder="Buscar..." type="text" className="form-control" onInput={self.handleChange()} onKeyPress={self.handleSearch()} />
              </div>
            </div>

            <div className="col-md-3">
              <button type="button" className="btn btn-success" onClick={self.handleCreate()}>
                <i className="material-icons">add</i> Nuevo
              </button>
            </div>
          </div>

          <Table items={state.items} onGet={self.getAlarm()} onDelete={self.deleteAlarm()} onOptions={self.handleOptions()}  />
        </div>
      );
    })();

    if (form == CREATE_FORM) {
      view = createForm;
    } else if (form == UPDATE_FORM) {
      view = updateForm;
    } else if (form == OPTIONS_PANEL) {
      view = optionsPanel;
    } else {
      view = table;
    }

    return (
      <div>
        {view}
      </div>
    );
  }
}

render(<Content />, document.getElementById('content-main'));