import { h, render, Component, options } from 'preact';

import constants from './../constants';

const VARIABLE = 1;
const CUSTOM_VARIABLE = 2;

class OptionsForm extends Component {

  constructor(props) {
    super(props);

    this.state = {
      variables_: [],
      custom_variables_: [],

      variables: [],
      custom_variables: []
    };
  }

  componentDidMount() {
    this.getVariables();
    this.getCustomVariables();

    this.getVariablesForAlarm();
    this.getCustomVariablesForAlarm();
  }

  getVariables() {
    let self = this;

    let url = `${constants.URL_SERVER_VARIABLES}/list`;

    let xhr = $.ajax({
      url: url,
      type: constants.METHOD_GET,
      dataType: constants.JSON,
    });

    xhr.done((res, status, response) => {
      if (response.status == constants.STATUS_OK) {
        self.setState({ variables_: res.docs });

      } else if (response.status == constants.STATUS_ACCEPTED) {
        alert(res.message);
      }
    });

    xhr.fail((res, status, respose) => {
      if (res.responseJSON) {
        let json = res.responseJSON;
        alert(json.message);
      } else {
        alert(constants.MESSAGE_ERROR);
      }
    });
  }

  getCustomVariables() {
    let self = this;

    let url = `${constants.URL_SERVER_CUSTOM_VARIABLES}/list`;

    let xhr = $.ajax({
      url: url,
      type: constants.METHOD_GET,
      dataType: constants.JSON,
    });

    xhr.done((res, status, response) => {
      if (response.status == constants.STATUS_OK) {
        self.setState({ custom_variables_: res.docs });

      } else if (response.status == constants.STATUS_ACCEPTED) {
        alert(res.message);
      }
    });

    xhr.fail((res, status, respose) => {
      if (res.responseJSON) {
        let json = res.responseJSON;
        alert(json.message);
      } else {
        alert(constants.MESSAGE_ERROR);
      }
    });
  }

  getVariablesForAlarm() {
    let self = this;

    let alarm = this.props.item;
    if (!alarm) {
      let msg = 'No se encontró la información de la alarma';
      alert(msg);
      return;
    }

    let url = `${constants.URL_SERVER_VARIABLES}/list?alarm_id=${alarm.id}`;

    let xhr = $.ajax({
      url: url,
      type: constants.METHOD_GET,
      dataType: constants.JSON,
    });

    xhr.done((res, status, response) => {
      if (response.status == constants.STATUS_OK) {
        self.setState({ variables: res.docs });

      } else if (response.status == constants.STATUS_ACCEPTED) {
        alert(res.message);
      }
    });

    xhr.fail((res, status, respose) => {
      if (res.responseJSON) {
        let json = res.responseJSON;
        alert(json.message);
      } else {
        alert(constants.MESSAGE_ERROR);
      }
    });
  }

  getCustomVariablesForAlarm() {
    let self = this;

    let alarm = this.props.item;
    if (!alarm) {
      let msg = 'No se encontró la información de la alarma';
      alert(msg);
      return;
    }

    let url = `${constants.URL_SERVER_CUSTOM_VARIABLES}/list?alarm_id=${alarm.id}`;

    let xhr = $.ajax({
      url: url,
      type: constants.METHOD_GET,
      dataType: constants.JSON,
    });

    xhr.done((res, status, response) => {
      if (response.status == constants.STATUS_OK) {
        self.setState({ custom_variables: res.docs });

      } else if (response.status == constants.STATUS_ACCEPTED) {
        alert(res.message);
      }
    });

    xhr.fail((res, status, respose) => {
      if (res.responseJSON) {
        let json = res.responseJSON;
        alert(json.message);
      } else {
        alert(constants.MESSAGE_ERROR);
      }
    });
  }    

  handleBack() {
    let self = this;

    let fn = () => {
      self.props.onBack();
    };

    return fn;
  }

  handleInsert(value) {
    let self = this;

    let fn = () => {
      let selector = false;

      if (value == VARIABLE) {
        selector = '#input-variable';
      } else if (value == CUSTOM_VARIABLE) {
        selector = '#input-custom-variable';
      }

      let inputValue = document.querySelector(selector);
      let sId = inputValue.value.trim();
      if (sId == '') return;

      let id = parseInt(sId);

      let insertValue = false;
      let items_ = [];

      if (value == VARIABLE) {
        items_ = self.state.variables_;
      } else if (value == CUSTOM_VARIABLE) {
        items_ = self.state.custom_variables_;
      }

      for (let i = 0; i < items_.length; i++) {
        const item_ = items_[i];
        if (item_.id == id) {
          insertValue = item_;
          break;
        }
      }

      if (insertValue) {
        let items = [];

        if (value == VARIABLE) {
          items = self.state.variables;
        } else if (value == CUSTOM_VARIABLE) {
          items = self.state.custom_variables;
        }

        for (let i = 0; i < items.length; i++) {
          const item = items[i];
          if (item.id == insertValue.id) return;
        }

        items.push(insertValue);

        if (value == VARIABLE) {
          self.setState({ variables: items });
        } else if (value == CUSTOM_VARIABLE) {
          self.setState({ custom_variables: items });
        }
      }
    };

    return fn;
  }

  handleUpdate(value) {
    let self = this;

    let fn = () => {
      let alarm = self.props.item;
      if (!alarm) {
        alert('No se cuenta con la información de la alarma');
        return;
      }

      let items = [];
      let key = false;
      
      if (value == VARIABLE) {
        items = self.state.variables;
        key = 'variables';
      } else if (value == CUSTOM_VARIABLE) {
        items = self.state.custom_variables;
        key = 'custom_variables';
      }

      let size = items.length;
      if (size == 0) {
        alert('La lista de elementos esta vacia, si desea eliminar los elementos, use el boton de limpiar');
        return;
      }

      let s = [];
      for (let i = 0; i < size; i++) {
        const item = items[i];
        let id = item.id;
        s.push(id);
      }

      let id = alarm.id;

      let json = {};
      json[key] = s;

      self.props.onUpdateOptions(json, id);
    };

    return fn;
  }

  handleUpdateClear(value) {
    let self = this;

    let fn = () => {
      let alarm = self.props.item;
      if (!alarm) {
        alert('No se cuenta con la información de la alarma');
        return;
      }

      let items = [];
      let key = false;

      if (value == VARIABLE) {
        key = 'variables';
      } else if (value == CUSTOM_VARIABLE) {
        key = 'custom_variables';
      }

      let id = alarm.id;

      let json = {};
      json[key] = [-1];

      self.props.onUpdateOptions(json, id);
    };

    return fn;
  }

  handleRemove(item, value) {
    let self = this;

    let fn = () => {
      let items = [];

      if (value == VARIABLE) {
        items = self.state.variables;

      } else if (value == CUSTOM_VARIABLE) {
        items = self.state.custom_variables;
      }

      let id = item.id;
      let update = false;
      for (let i = 0; i < items.length; i++) {
        const o = items[i];
        if (o.id == id) {
          items.splice(i, 1);
          update = true;
        }
      }

      if (update) {
        if (value == VARIABLE) {
          self.setState({ variables: items });

        } else if (value == CUSTOM_VARIABLE) {
          self.setState({ custom_variables: items });
        }
      }
    };

    return fn;
  }

  createOptVariable() {
    let self = this;

    let fn = (item, index) => {
      return <option key={item.id} value={item.id}>{item.device}.{item.name}</option>;
    };

    return fn;
  }

  createItem(value) {
    let self = this;

    let fn = (item, index) => {
      return (
        <li className="list-group-item" key={item.id}>
          {item.device}.{item.name}
          <button type="button" className="close" data-dismiss="modal" aria-label="Close" onClick={self.handleRemove(item, value)}>
            <span aria-hidden="true">&times;</span>
          </button>
        </li>
      );
    };

    return fn;
  }  

  render(props, state) {
    let alarm = props.item;

    return (
      <section>

        <div className="row">
          <div className="col-md-2">
            <button type="button" className="btn btn-primary" onClick={this.handleBack()}>
              <i className="material-icons">arrow_back</i>
            </button>
          </div>
          <div className="col-md-10">
            <h2>Alarma: {alarm.name}</h2>
          </div>
        </div>

        <div className="row">
          <div className="col-md-12">
            <ul class="nav nav-tabs" id="tab-panel" role="tablist">
              <li class="nav-item">
                <a class="nav-link active" id="variables-tab" data-toggle="tab" href="#variables" role="tab" aria-controls="variables" aria-selected="true">Variables</a>
              </li>
              <li class="nav-item">
                <a class="nav-link" id="custom-variables-tab" data-toggle="tab" href="#custom-variables" role="tab" aria-controls="custom-variables" aria-selected="true">Variables personalizadas</a>
              </li>              
            </ul>
          </div>

          <div className="col-md-12">
            <div class="tab-content" id="content-panel">

              <div class="tab-pane fade show active" id="variables" role="tabpanel" aria-labelledby="variables-tab">

                <h4>Variables</h4>

                <div className="row">

                  <div className="col-md-4">
                    <select class="form-control" id="input-variable">
                      <option>Variables</option>
                      {state.variables_.map(this.createOptVariable())}
                    </select>
                  </div>

                  <div className="col-md-4">
                    <button type="button" className="btn btn-primary" onClick={this.handleInsert(VARIABLE)}>
                      <i className="material-icons">add</i>
                    </button>
                  </div>

                  <div className="col-md-2">
                    <button type="button" className="btn btn-success" onClick={this.handleUpdate(VARIABLE)}>
                      <i className="material-icons">save</i>
                    </button>
                  </div>

                  <div className="col-md-2">
                    <button type="button" className="btn btn-danger" onClick={this.handleUpdateClear(VARIABLE)}>
                      <i className="material-icons">delete_sweep</i>
                    </button>
                  </div>

                  <div className="col-md-12" style={{ marginTop: '10px' }}>
                    <ul className="list-group">
                      {state.variables.map(this.createItem(VARIABLE))}
                    </ul>
                  </div>

                </div>

              </div>

              <div class="tab-pane fade show" id="custom-variables" role="tabpanel" aria-labelledby="custom-variables-tab">

                <h4>Variables personalizadas</h4>

                <div className="row">

                  <div className="col-md-4">
                    <select class="form-control" id="input-custom-variable">
                      <option>Variables personalizadas</option>
                      {state.custom_variables_.map(this.createOptVariable())}
                    </select>
                  </div>

                  <div className="col-md-4">
                    <button type="button" className="btn btn-primary" onClick={this.handleInsert(CUSTOM_VARIABLE)}>
                      <i className="material-icons">add</i>
                    </button>
                  </div>

                  <div className="col-md-2">
                    <button type="button" className="btn btn-success" onClick={this.handleUpdate(CUSTOM_VARIABLE)}>
                      <i className="material-icons">save</i>
                    </button>
                  </div>

                  <div className="col-md-2">
                    <button type="button" className="btn btn-danger" onClick={this.handleUpdateClear(CUSTOM_VARIABLE)}>
                      <i className="material-icons">delete_sweep</i>
                    </button>
                  </div>

                  <div className="col-md-12" style={{ marginTop: '10px' }}>
                    <ul className="list-group">
                      {state.custom_variables.map(this.createItem(CUSTOM_VARIABLE))}
                    </ul>
                  </div>

                </div>

              </div>              

            </div>
          </div>

        </div>


      </section> 
    );
  }
}

export default OptionsForm;
