import { h, render, Component, options } from 'preact';

import constants from './../constants';

class CreateForm extends Component {

  constructor(props) {
    super(props);

    this.state = {
      units_: [],
      is_timeout: false,
    };
  }

  componentDidMount() {
    this.getUnits();
  }

  getUnits() {
    let self = this;

    let url = `${constants.URL_SERVER_UNITS}/list`;

    let xhr = $.ajax({
      url: url,
      type: constants.METHOD_GET,
      dataType: constants.JSON,
    });

    xhr.done((res, status, response) => {
      if (response.status == constants.STATUS_OK) {
        self.setState({ units_: res.docs });

      } else if (response.status == constants.STATUS_ACCEPTED) {
        alert(res.message);
      }
    });

    xhr.fail((res, status, respose) => {
      if (res.responseJSON) {
        let json = res.responseJSON;
        alert(json.message);
      } else {
        alert(constants.MESSAGE_ERROR);
      }
    });
  }

  handleCreate() {
    let self = this;

    let fn = (evt) => {
      evt.preventDefault();

      let inputName = document.querySelector('#input-c-name');
      let inputUnit = document.querySelector('#input-c-unit');
      let inputColor = document.querySelector('#input-c-color');
      let inputIsTimeout = document.querySelector('#input-c-is-timeout');
      let inputTimeout = document.querySelector('#input-c-timeout');
      let inputExpression = document.querySelector('#input-c-expression');
      let inputMessage = document.querySelector('#input-c-message');
      let inputSound = document.querySelector('#input-c-sound');
      let inputStatus = document.querySelector('#input-c-status');

      let name = inputName.value.trim();
      let unit = inputUnit.value.trim();
      let color = inputColor.value.trim();
      let is_timeout = inputIsTimeout.checked;
      let message = inputMessage.value.trim();
      let sound = inputStatus.value.trim();
      let status = inputStatus.checked;

      let expression, timeout;

      if (is_timeout) {
        timeout = inputTimeout.value.trim();
        timeout = parseInt(timeout);
      } else {
        expression = inputExpression.value.trim();
      }

      let json = {};

      if (unit !== '') {
        let unit_id = parseInt(unit);
        json.unit_id = unit_id;
      }

      if (sound == '') {
        sound = -1;
      } else {
        sound = parseInt(sound);
      }

      json.name = name;
      json.color = color;
      json.expression = expression;
      json.is_timeout = is_timeout;
      json.timeout = timeout;
      json.message = message;
      json.sound = sound;
      json.status = status;

      self.props.onCreate(json);
    };

    return fn;
  }

  handleChangeTimeout() {
    let self = this;

    let fn = (evt) => {
      let value = evt.target.checked;
      self.setState({ is_timeout: value });
    };

    return fn;
  }

  handleBack() {
    let self = this;

    let fn = () => {
      self.props.onBack();
    };

    return fn;
  }

  createOptUnit() {
    let self = this;

    let fn = (item, index) => {
      return <option key={item.id} value={item.value}>{item.name}</option>;
    };

    return fn;
  }

  render(props, state) {
    return (
      <section>
        <div className="row">
          <div className="col-md-12">
            <h3>Crear Alarma</h3>

            <form onSubmit={this.handleCreate()} >

              <div className="form-group">
                <label htmlFor="input-c-name">Nombre</label>
                <input type="text" className="form-control" id="input-c-name" placeholder="Nombre" />
              </div>

              <div className="form-group">
                <label htmlFor="input-c-unit">Unidad</label>
                <select id="input-c-unit" className="form-control">
                  <option selected value="-1">Unidad</option>
                  {state.units_.map(this.createOptUnit())}
                </select>
              </div>

              <div className="form-group">
                <label htmlFor="input-c-color">Color</label>
                <input type="text" className="form-control" id="input-c-color" placeholder="Color" />
              </div>

              <div className="form-check">
                <input type="checkbox" class="form-check-input" id="input-c-is-timeout" onChange={this.handleChangeTimeout()} />
                <label class="form-check-label" htmlFor="input-c-is-timeout">Tiempo de Espera</label>
              </div>

              <br/>

              <div className="form-group" hidden={!state.is_timeout}>
                <label htmlFor="input-c-timeout">Tiempo</label>
                <input type="text" className="form-control" id="input-c-timeout" placeholder="Tiempo (Minutos)" />
              </div>

              <div className="form-group" hidden={state.is_timeout}>
                <label htmlFor="input-c-expression">
                  Expresión Booleana
                  <br />
                  {'${value}: Valor de la Variable'}
                </label>
                <textarea className="form-control" id="input-c-expression" placeholder="Expresión Booleana" />
              </div>         

              <div className="form-group">
                <label htmlFor="input-c-message">
                  Mensaje
                  <br />
                  {'${name}: Nombre de la Alarma'}
                  <br />
                  {'${variable}: Nombre de la Variable'}
                  <br />
                  {'${value}: Valor de la Variable'}
                  <br />
                  {'${timestamp}: Estampa de tiempo de la variable'}
                </label>
                <textarea className="form-control" id="input-c-message" placeholder="Mensaje" />
              </div>

              <div className="form-group">
                <label htmlFor="input-c-sound">Sonido</label>
                <select id="input-c-sound" className="form-control">
                  <option selected value="-1">Sin sonido</option>
                  <option value="1">Advertencia</option>
                  <option value="2">Peligro</option>
                </select>
              </div>

              <div className="form-check">
                <input type="checkbox" class="form-check-input" id="input-c-status" />
                <label class="form-check-label" htmlFor="input-c-status">Activada</label>
              </div>

              <div className="form-group col-md-12">
                <br />
                <br />
                <button type="button" className="btn btn-warning" onClick={this.handleBack()}>Cancelar</button>
                <button type="submit" className="btn btn-success">Guardar</button>
              </div>

            </form>
          </div>
        </div>
      </section>
    );
  }
}

export default CreateForm;
