import { h, render, Component } from 'preact';

import constants from './../constants';

class RowTable extends Component {

  constructor(props) {
    super(props);
  }

  handleGet() {
    let self = this;

    let fn = () => {
      let json = self.props.row;
      self.props.onGet(json);
    };

    return fn;
  }

  handleOptions() {
    let self = this;

    let fn = () => {
      let json = self.props.row;
      self.props.onOptions(json);
    };

    return fn;
  }  

  handleDelete() {
    let self = this;

    let fn = () => {
      let json = self.props.row;
      let name = json.name;

      let message = `¿Desea eliminar la alarma: ${name}?`;
      let result = window.confirm(message);
      if (result) {
        self.props.onDelete(json);
      }
    };

    return fn;
  }

  render() {
    let row = this.props.row;

    let unitName = 'N/A';
    if (row.unit_name) {
      unitName = row.unit_name
    }

    let timeout = 'N/A';
    let expression = 'N/A';    
    if (row.is_timeout) {
      timeout = `${row.timeout} Min.`;
    } else {
      expression = row.expression;
    }

    let sound = 'Sin sonido';
    if (row.sound == constants.WARNING_SOUND) {
      sound = 'Advertencia';
    } else if (row.sound == constants.DANGER_SOUND) {
      sound = 'Peligro';
    }

    let status = 'Inactiva';
    if (row.status) {
      status = 'Activa';
    }

    return (
      <tr>
        <td>{row.index}</td>
        <td>{row.name}</td>
        <td>{row.color}</td>
        <td>{timeout}</td>
        <td>{expression}</td>
        <td>{row.message}</td>
        <td>{unitName}</td>
        <td>{sound}</td>
        <td>{status}</td>
        <td>
          <button type="button" className="btn btn-primary" onClick={this.handleOptions()}>
            <i className="material-icons">developer_board</i>
          </button>

          <button type="button" className="btn btn-info" onClick={this.handleGet()}>
            <i className="material-icons">mode_edit</i>
          </button>

          <button type="button" className="btn btn-danger" onClick={this.handleDelete()}>
            <i className="material-icons">delete</i>
          </button>
        </td>
      </tr>
    );
  }
}

class Table extends Component {

  constructor(props) {
    super(props);

    this.state = { rows: false };
  }

  handleGet() {
    let self = this;

    let fn = (json) => {
      self.props.onGet(json);
    };

    return fn;
  }

  handleOptions() {
    let self = this;

    let fn = (json) => {
      self.props.onOptions(json);
    };

    return fn;
  }  

  handleDelete() {
    let self = this;

    let fn = (json) => {
      self.props.onDelete(json);
    };

    return fn;
  }

  createRow() {
    let self = this;

    let fn = (item, index) => {
      item.index = index + 1;
      return <RowTable key={item.id} row={item} onGet={self.handleGet()} onDelete={self.handleDelete()} onOptions={self.handleOptions()} />;
    };

    return fn;
  }

  render() {
    let items = this.props.items;
    let rows = this.state.rows;

    if (items.length > 0) {
      rows = items.map(this.createRow());
    }

    if (!rows) {
      rows = <tr><td className="center" colSpan="8">Sin alarmas registradas</td></tr>;
    }

    return (
      <section>
        <div className="row">
          <table className="table table-hover">
            <thead>
              <tr>
                <th>Nº</th>
                <th>Nombre</th>
                <th>Color</th>
                <th>Tiempo de Espera</th>
                <th>Expresión</th>
                <th>Mensaje</th>
                <th>Unidad</th>
                <th>Sonido</th>
                <th>Estado</th>
                <th></th>
              </tr>
            </thead>
            <tbody>
              {rows}
            </tbody>
          </table>
        </div>
      </section>
    );
  }
}

export default Table;
